import { applyDocumentLanguage, bindLanguageSwitcher, nextLanguage, persistLanguage, subjectLabel } from './i18n.js';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[character]));
const formatDate = (value) => { const raw = String(value || ''); const date = new Date(/^\d{4}-\d{2}-\d{2} \d/.test(raw) ? raw.replace(' ', 'T') + 'Z' : raw); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleDateString('en-GB'); };
async function api(path, options = {}) { const response = await fetch(path, { credentials: 'include', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.error || 'Something went wrong.'); return payload; }
function formMessage(target, message, type = 'error') { target.textContent = message; target.className = `phase3-message ${type}`; }
function routeShell(content) { document.body.classList.add('phase3-route-mode'); $('#app').innerHTML = `<div class="phase3-route-shell"><a class="wordmark phase3-route-wordmark" href="/"><span class="wordmark-mark">l<span>·</span></span>inguora</a><button class="route-language-toggle" id="route-language-toggle" type="button">EN / ES / AR</button>${content}</div>`; bindLanguageSwitcher('#route-language-toggle'); }
function passwordField(id, label) { return `<label class="phase3-field"><span>${label}</span><input id="${id}" type="password" autocomplete="new-password" required /></label>`; }
function renderTeacherSetup() { window.location.replace('/admin'); }
function renderTeacherLogin() { routeShell(`<main class="phase3-auth-card compact teacher-login-card"><div class="phase3-kicker">TEACHER PORTAL <i></i></div><h1>Welcome back,<br /><em>teacher.</em></h1><p class="phase3-auth-copy">Choose your subject, then enter the credentials created for you by the Super Admin.</p><form id="phase3-login-form" class="phase3-form"><label class="phase3-field"><span>Username</span><input id="phase3-login-username" type="text" autocomplete="username" required /></label>${passwordField('phase3-login-password', 'Password')}<fieldset class="teacher-subject-selector"><legend>Assigned subject</legend><div class="teacher-subject-options"><label><input type="radio" name="teacher-subject" value="spanish" checked /><span>🇪🇸 Spanish</span></label><label><input type="radio" name="teacher-subject" value="english" /><span>🇬🇧 English</span></label><label><input type="radio" name="teacher-subject" value="arabic" /><span>ع Arabic</span></label></div></fieldset><div id="phase3-login-message" class="phase3-message" role="status"></div><button class="btn btn-primary phase3-submit" type="submit"><span>Enter subject dashboard</span><span>↗</span></button></form><a class="phase3-backlink" href="/">← Back to Linguora</a></main>`); $('#phase3-login-form').addEventListener('submit', async (event) => { event.preventDefault(); try { const result = await api('/api/teacher/login', { method: 'POST', body: JSON.stringify({ username: $('#phase3-login-username').value, password: $('#phase3-login-password').value, subject: document.querySelector('input[name=\"teacher-subject\"]:checked')?.value }) }); if (result.user.role !== 'teacher') throw new Error('This account is not a teacher profile.'); window.location.href = '/'; } catch (error) { formMessage($('#phase3-login-message'), error.message); } }); }
function renderStudentSignup() { routeShell(`<main class="phase3-auth-card"><div class="phase3-kicker">STUDENT REGISTRATION <i></i></div><h1>Make space for<br /><em>the next hello.</em></h1><p class="phase3-auth-copy">Create your learner profile. Your teacher will see you in the registered student directory immediately.</p><form id="phase3-student-signup" class="phase3-form"><div class="phase3-two-col"><label class="phase3-field"><span>First name</span><input id="student-first-name" type="text" required /></label><label class="phase3-field"><span>Last name</span><input id="student-last-name" type="text" required /></label></div><label class="phase3-field"><span>Email</span><input id="student-email" type="email" required /></label><label class="phase3-field"><span>Phone / WhatsApp number</span><input id="student-phone" type="tel" required /></label>${passwordField('student-password', 'Password · 8+ characters')}<div id="student-signup-message" class="phase3-message" role="status"></div><button class="btn btn-primary phase3-submit" type="submit"><span>Create student account</span><span>↗</span></button></form><a class="phase3-backlink" href="/student/login">Already registered? Log in →</a></main>`); $('#phase3-student-signup').addEventListener('submit', async (event) => { event.preventDefault(); try { const result = await api('/api/student/signup', { method: 'POST', body: JSON.stringify({ firstName: $('#student-first-name').value, lastName: $('#student-last-name').value, email: $('#student-email').value, phone: $('#student-phone').value, password: $('#student-password').value }) }); formMessage($('#student-signup-message'), `Welcome, ${result.user.fullName}. Opening your learner space…`, 'success'); setTimeout(() => { window.location.href = '/student'; }, 650); } catch (error) { formMessage($('#student-signup-message'), error.message); } }); }
function renderStudentLogin() { routeShell(`<main class="phase3-auth-card compact"><div class="phase3-kicker">STUDENT PORTAL <i></i></div><h1>Your next lesson<br /><em>is waiting.</em></h1><form id="phase3-student-login" class="phase3-form"><label class="phase3-field"><span>Email</span><input id="student-login-identifier" type="email" required /></label>${passwordField('student-login-password', 'Password')}<div id="student-login-message" class="phase3-message" role="status"></div><button class="btn btn-primary phase3-submit" type="submit"><span>Open learner space</span><span>↗</span></button></form><a class="phase3-backlink" href="/student/signup">Need an account? Sign up →</a></main>`); $('#phase3-student-login').addEventListener('submit', async (event) => { event.preventDefault(); try { await api('/api/student/login', { method: 'POST', body: JSON.stringify({ identifier: $('#student-login-identifier').value, password: $('#student-login-password').value }) }); window.location.href = '/student'; } catch (error) { formMessage($('#student-login-message'), error.message); } }); }
function youtubeEmbed(url = '') { const match = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/))([\w-]{6,})/i); return match ? `https://www.youtube-nocookie.com/embed/${match[1]}` : ''; }
function lessonMedia(lesson) { const url = String(lesson.videoUrl || ''); const embed = youtubeEmbed(url); const video = embed ? `<iframe class="student-video-frame" src="${embed}" title="${escapeHtml(lesson.title)} video" loading="lazy" allowfullscreen></iframe>` : /^https?:\/\//i.test(url) ? `<video class="student-video-frame" controls preload="metadata" src="${escapeHtml(url)}"></video>` : url ? `<div class="media-file-note">Video asset: ${escapeHtml(url)}</div>` : ''; const pdf = lesson.pdfUrl ? `<a class="lesson-pdf-link" href="${escapeHtml(lesson.pdfUrl)}" target="_blank" rel="noopener">PDF study sheet ↗</a>` : ''; return video || pdf ? `<div class="student-lesson-media">${video}${pdf}</div>` : ''; }
async function refreshStudentContent() { const { courses } = await api('/api/student/content'); $('#student-course-count').textContent = `${courses.length} COURSE${courses.length === 1 ? '' : 'S'}`; $('#student-content').innerHTML = courses.length ? courses.map((course) => `<article class="student-course-card"><div class="student-course-card-head"><span class="subject-chip chip-${escapeHtml(course.subject)}">${course.subject === 'english' ? '🇬🇧 English' : course.subject === 'arabic' ? 'ع العربية' : '🇪🇸 Spanish'}</span><small>${escapeHtml(course.grade)} · targeted access</small></div><h3>${escapeHtml(course.title)}</h3><div class="student-lesson-list">${course.lessons.map((lesson) => `<div class="student-lesson-row"><span class="student-lesson-number">${String(lesson.unitNumber).padStart(2, '0')}</span><span><strong>${escapeHtml(lesson.title)}</strong><small>${lesson.videoUrl ? 'Video ready' : 'Lesson'} ${lesson.pdfUrl ? '· PDF sheet ready' : ''}</small></span><span class="student-lesson-actions">${lesson.completed ? '<b class="lesson-done">✓ Complete</b>' : `<button class="lesson-complete" data-lesson-id="${lesson.id}" type="button">Mark complete</button>`}<button class="lesson-quiz" data-lesson-id="${lesson.id}" type="button">Quiz ↗</button></span></div>${lessonMedia(lesson)}`).join('')}</div><a class="certificate-link" href="/api/student/certificate/${course.id}">Download certificate ↗</a></article>`).join('') : '<div class="student-empty"><span>✦</span><strong>Your first course will appear here.</strong><small>Ask your teacher for an access code to begin.</small></div>'; $$('.lesson-complete').forEach((button) => button.addEventListener('click', async () => { await api(`/api/student/lessons/${button.dataset.lessonId}/complete`, { method: 'POST' }); await refreshStudentContent(); })); $$('.lesson-quiz').forEach((button) => button.addEventListener('click', () => launchQuiz(button.dataset.lessonId))); }
async function launchQuiz(lessonId) { const { attemptId, questions, total } = await api(`/api/student/quiz/${lessonId}/start`); const overlay = document.createElement('div'); overlay.className = 'quiz-overlay'; overlay.innerHTML = `<div class="quiz-modal"><button class="quiz-close" type="button">×</button><span class="mini-label">RANDOMIZED UNIT QUIZ</span><h2>Say it<br /><em>like you mean it.</em></h2><form id="quiz-form">${questions.map((question, index) => `<fieldset><legend><span>0${index + 1}</span>${escapeHtml(question.question)}</legend>${question.choices.map((choice) => `<label><input type="radio" name="question-${question.id}" value="${choice.key}" required /><span>${choice.key}</span>${escapeHtml(choice.text)}</label>`).join('')}</fieldset>`).join('')}<button class="btn btn-primary" type="submit"><span>Submit ${total} answers</span><span>↗</span></button><div id="quiz-message" class="phase3-message" role="status"></div></form></div>`; document.body.appendChild(overlay); $('.quiz-close', overlay).addEventListener('click', () => overlay.remove()); $('#quiz-form', overlay).addEventListener('submit', async (event) => { event.preventDefault(); const answers = Object.fromEntries(questions.map((question) => [question.id, $(`input[name="question-${question.id}"]:checked`, overlay)?.value])); const result = await api(`/api/student/quiz/${attemptId}/submit`, { method: 'POST', body: JSON.stringify({ answers }) }); formMessage($('#quiz-message', overlay), result.passed ? 'Perfect score. Your certificate is now available after progress is complete.' : `You scored ${result.score}/${result.total}. Review the lesson and try again.`, result.passed ? 'success' : 'error'); if (result.passed) setTimeout(() => { overlay.remove(); refreshStudentContent(); }, 1000); }); }
async function renderStudentDashboard() { document.body.classList.add('student-mode'); routeShell(`<main class="student-dashboard"><header class="student-dashboard-head"><div><div class="phase3-kicker">LINGUORA / LEARNER SPACE <i></i></div><h1>Keep your<br /><em>curiosity close.</em></h1></div><button class="student-logout" id="student-logout" type="button">Log out ↗</button></header><section class="student-redemption"><div><span class="mini-label">UNLOCK A COURSE</span><h2>One code.<br /><em>A fuller world.</em></h2><p>Paste the access code your teacher gave you and your units will open instantly.</p></div><form id="redeem-form"><input id="redeem-code" type="text" placeholder="LNG-XXXX-XXXX" autocomplete="off" /><button class="btn btn-primary" type="submit"><span>Redeem code</span><span>↗</span></button><div id="redeem-message" class="phase3-message" role="status"></div></form></section><section><div class="student-section-head"><div><span class="mini-label">YOUR UNLOCKED PATHS</span><h2>Lessons with momentum.</h2></div><span id="student-course-count" class="panel-note">0 COURSES</span></div><div id="student-content" class="student-course-list"><div class="student-loading">Loading your space…</div></div></section>${studentChatMarkup()}</main>`); bindStudentChat(); $('#student-logout').addEventListener('click', async () => { await api('/api/auth/logout', { method: 'POST' }); window.location.href = '/'; }); $('#redeem-form').addEventListener('submit', async (event) => { event.preventDefault(); try { await api('/api/student/redeem-code', { method: 'POST', body: JSON.stringify({ code: $('#redeem-code').value }) }); formMessage($('#redeem-message'), 'Course unlocked. Your lessons are ready below.', 'success'); $('#redeem-code').value = ''; await refreshStudentContent(); } catch (error) { formMessage($('#redeem-message'), error.message); } }); await refreshStudentContent(); }

function studentChatMarkup() { return `<aside class="student-chatbot" id="student-chatbot"><button class="student-chat-toggle" id="student-chat-toggle" type="button" aria-expanded="false" aria-controls="student-chat-panel"><span class="chat-spark">✦</span><span>Study companion</span><b>↗</b></button><div class="student-chat-panel" id="student-chat-panel" hidden><header><div><span class="mini-label">LINGUAEDU AI</span><h3>Your study companion</h3></div><button id="student-chat-close" type="button" aria-label="Close chat">×</button></header><div class="student-chat-context"><span class="chat-status-dot"></span><span id="student-chat-subject">Subject-aware help</span><span class="chat-powered">READY</span></div><div class="student-chat-messages" id="student-chat-messages"><div class="student-chat-message assistant"><span class="chat-avatar">✦</span><p>Ask me about grammar, vocabulary, or a revision plan. I’ll keep the explanation clear and practical.</p></div></div><form class="student-chat-form" id="student-chat-form"><textarea id="student-chat-input" rows="2" maxlength="1200" placeholder="Ask a study question…" required></textarea><button type="submit" aria-label="Send message">↗</button></form><small class="student-chat-note">AI support for learning — always check your lesson materials too.</small></div></aside>`; }
function bindStudentChat() {
  const toggle = $('#student-chat-toggle'); const panel = $('#student-chat-panel'); const close = $('#student-chat-close'); const form = $('#student-chat-form'); const input = $('#student-chat-input'); const messages = $('#student-chat-messages'); if (!toggle || !panel || !form) return;
  const open = () => { panel.hidden = false; toggle.setAttribute('aria-expanded', 'true'); setTimeout(() => input.focus(), 50); }; const shut = () => { panel.hidden = true; toggle.setAttribute('aria-expanded', 'false'); };
  toggle.onclick = () => panel.hidden ? open() : shut(); close.onclick = shut;
  const addMessage = (text, role) => { const item = document.createElement('div'); item.className = `student-chat-message ${role}`; item.innerHTML = `<span class="chat-avatar">${role === 'assistant' ? '✦' : 'You'}</span><p>${escapeHtml(text).replace(/\n/g, '<br />')}</p>`; messages.appendChild(item); messages.scrollTop = messages.scrollHeight; return item; };
  form.onsubmit = async (event) => { event.preventDefault(); const message = input.value.trim(); if (!message) return; addMessage(message, 'user'); input.value = ''; input.disabled = true; form.querySelector('button').disabled = true; const pending = addMessage('Thinking through that with your subject in mind…', 'assistant pending'); try { const result = await api('/api/student/chat', { method: 'POST', body: JSON.stringify({ message }) }); pending.querySelector('p').textContent = result.reply; } catch (error) { pending.querySelector('p').textContent = error.message; } finally { pending.classList.remove('pending'); input.disabled = false; form.querySelector('button').disabled = false; input.focus(); } };
}

let teacherCourses = [];
function openConfirm(title, detail, action) { const overlay = document.createElement('div'); overlay.className = 'content-modal-backdrop'; overlay.innerHTML = `<div class="content-modal confirm-modal" role="dialog" aria-modal="true"><button class="content-modal-close" type="button">×</button><span class="mini-label">CONFIRM ACTION</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(detail)}</p><div class="content-modal-actions"><button class="btn btn-outline content-cancel" type="button">Cancel</button><button class="btn btn-danger content-confirm" type="button">Confirm delete</button></div></div>`; document.body.appendChild(overlay); const close = () => overlay.remove(); $$('.content-modal-close, .content-cancel', overlay).forEach((button) => button.addEventListener('click', close)); $('.content-confirm', overlay).addEventListener('click', async () => { $('.content-confirm', overlay).disabled = true; try { await action(); close(); await syncTeacherDashboard(); } catch (error) { alert(error.message); $('.content-confirm', overlay).disabled = false; } }); }
function openContentEditor({ lesson, bank = null, focus = '' }) { const isBank = Boolean(bank); const overlay = document.createElement('div'); overlay.className = 'content-modal-backdrop'; overlay.innerHTML = `<div class="content-modal" role="dialog" aria-modal="true"><button class="content-modal-close" type="button">×</button><span class="mini-label">${isBank ? 'EDIT QUESTION BANK' : 'EDIT LESSON CONTENT'}</span><h3>${escapeHtml(isBank ? `Questions · ${lesson.title}` : lesson.title)}</h3>${isBank ? `<label class="field-label">Parsed question text<textarea class="content-modal-textarea" id="modal-raw-questions">${escapeHtml(bank.rawText || '')}</textarea></label>` : `<label class="field-label">Lesson title<input class="text-input" id="modal-title" value="${escapeHtml(lesson.title)}" /></label><div class="phase3-two-col"><label class="field-label">Video URL / file metadata<input class="text-input" id="modal-video" value="${escapeHtml(lesson.videoUrl || '')}" /></label><label class="field-label">PDF URL / file metadata<input class="text-input" id="modal-pdf" value="${escapeHtml(lesson.pdfUrl || '')}" /></label></div><label class="field-label">Cover thumbnail URL / file metadata<input class="text-input" id="modal-cover" value="${escapeHtml(lesson.coverUrl || '')}" /></label>`}<div id="content-modal-message" class="phase3-message"></div><div class="content-modal-actions"><button class="btn btn-outline content-cancel" type="button">Cancel</button><button class="btn btn-primary content-save" type="button">Save changes</button></div></div>`; document.body.appendChild(overlay); const close = () => overlay.remove(); $$('.content-modal-close, .content-cancel', overlay).forEach((button) => button.addEventListener('click', close)); const focusNode = focus === 'video' ? $('#modal-video', overlay) : focus === 'pdf' ? $('#modal-pdf', overlay) : focus === 'cover' ? $('#modal-cover', overlay) : isBank ? $('#modal-raw-questions', overlay) : $('#modal-title', overlay); focusNode?.focus(); $('.content-save', overlay).addEventListener('click', async () => { try { if (isBank) await api(`/api/teacher/question-banks/${bank.id}`, { method: 'PUT', body: JSON.stringify({ rawText: $('#modal-raw-questions', overlay).value }) }); else await api(`/api/teacher/lessons/${lesson.id}`, { method: 'PUT', body: JSON.stringify({ title: $('#modal-title', overlay).value, videoUrl: $('#modal-video', overlay).value, pdfUrl: $('#modal-pdf', overlay).value, coverUrl: $('#modal-cover', overlay).value }) }); close(); await syncTeacherDashboard(); } catch (error) { formMessage($('#content-modal-message', overlay), error.message); } }); }
function assetActions(lesson, label, field) { const has = Boolean(lesson[field]); return `<div class="asset-row"><span><strong>${label}</strong><small>${has ? escapeHtml(lesson[field]) : 'Not attached'}</small></span><span class="asset-actions"><button class="asset-button" data-action="edit-asset" data-lesson-id="${lesson.id}" data-asset="${field}">${has ? 'Edit' : 'Add'}</button>${has ? `<button class="asset-button asset-delete" data-action="delete-asset" data-lesson-id="${lesson.id}" data-asset="${field}" data-label="${label}">Delete</button>` : ''}</span></div>`; }
function renderContentLibraries() {
  const courseLibrary = $('#teacher-course-library');
  if (courseLibrary) courseLibrary.innerHTML = teacherCourses.length ? teacherCourses.map((course) => `<article class="teacher-course-card"><div><span class="subject-chip chip-${escapeHtml(course.subject)}">${escapeHtml(course.subject)}</span><h4>${escapeHtml(course.title)}</h4><small>${escapeHtml(course.grade)} · ${course.lessonCount} lessons</small></div><button class="asset-button asset-delete" data-action="delete-course" data-course-id="${course.id}">Delete Course</button></article>`).join('') : '<div class="teacher-library-empty">No courses in the database yet.</div>';
  const lessons = teacherCourses.flatMap((course) => (course.lessons || []).map((lesson) => ({ ...lesson, subject: course.subject, grade: course.grade })));
  const library = $('#teacher-lesson-library');
  if (library) library.innerHTML = lessons.length ? lessons.map((lesson) => `<article class="teacher-content-card"><div class="teacher-content-card-head"><div><span class="subject-chip chip-${escapeHtml(lesson.subject)}">${escapeHtml(lesson.subject)}</span><h4>${escapeHtml(lesson.title)}</h4><small>${escapeHtml(lesson.grade)} · Unit ${lesson.unitNumber}</small></div><span class="content-card-actions"><button class="asset-button" data-action="edit-lesson" data-lesson-id="${lesson.id}">Edit lesson</button><button class="asset-button asset-delete" data-action="delete-lesson" data-lesson-id="${lesson.id}">Delete lesson</button></span></div>${assetActions(lesson, 'Video URL / upload', 'videoUrl')}${assetActions(lesson, 'Attached PDF', 'pdfUrl')}${assetActions(lesson, 'Cover thumbnail', 'coverUrl')}</article>`).join('') : '<div class="teacher-library-empty">No lessons in the database yet. Save the first lesson above.</div>';
  const banks = lessons.filter((lesson) => lesson.questionBank); const questionLibrary = $('#teacher-question-library');
  if (questionLibrary) questionLibrary.innerHTML = banks.length ? banks.map((lesson) => `<article class="teacher-content-card question-library-card"><div class="teacher-content-card-head"><div><span class="mini-label">${lesson.questionBank.questionCount} PARSED QUESTIONS</span><h4>${escapeHtml(lesson.title)}</h4><small>Stored in the live question-bank table</small></div><span class="content-card-actions"><button class="asset-button" data-action="edit-bank" data-lesson-id="${lesson.id}">Edit questions</button><button class="asset-button asset-delete" data-action="delete-bank" data-bank-id="${lesson.questionBank.id}" data-lesson-title="${escapeHtml(lesson.title)}">Delete questions</button></span></div><p class="question-bank-snippet">${escapeHtml(lesson.questionBank.rawText).slice(0, 220)}${lesson.questionBank.rawText.length > 220 ? '…' : ''}</p></article>`).join('') : '<div class="teacher-library-empty">No parsed question banks yet. Paste text and save a lesson to create one.</div>';
}
function bindContentActions() {
  const handler = async (event) => {
    const button = event.target.closest('[data-action]'); if (!button) return;
    const action = button.dataset.action;
    if (action === 'delete-course') { const course = teacherCourses.find((item) => String(item.id) === String(button.dataset.courseId)); if (!course) return; return openConfirm('Delete this course permanently?', 'Are you sure you want to permanently delete this course and all associated lessons, PDFs, and media?', () => api(`/api/teacher/courses/${course.id}`, { method: 'DELETE' })); }
    const lesson = teacherCourses.flatMap((course) => course.lessons || []).find((item) => String(item.id) === String(button.dataset.lessonId));
    if (action === 'edit-lesson') return openContentEditor({ lesson });
    if (action === 'edit-asset') return openContentEditor({ lesson, focus: button.dataset.asset.replace('Url', '').replace('cover', 'cover') });
    if (action === 'delete-lesson') return openConfirm('Delete this lesson?', 'The lesson, its question bank, views, progress, and quiz attempts will be removed from the database.', () => api(`/api/teacher/lessons/${lesson.id}`, { method: 'DELETE' }));
    if (action === 'delete-asset') return openConfirm(`Delete ${button.dataset.label}?`, 'This removes the stored media metadata from the lesson while keeping the lesson itself.', () => api(`/api/teacher/lessons/${lesson.id}`, { method: 'PUT', body: JSON.stringify({ [button.dataset.asset]: null }) }));
    if (action === 'edit-bank') return openContentEditor({ lesson, bank: lesson.questionBank });
    if (action === 'delete-bank') return openConfirm('Delete this question bank?', `Remove the parsed questions stored for ${button.dataset.lessonTitle}.`, () => api(`/api/teacher/question-banks/${button.dataset.bankId}`, { method: 'DELETE' }));
  };
  $('#teacher-course-library')?.addEventListener('click', handler); $('#teacher-lesson-library')?.addEventListener('click', handler); $('#teacher-question-library')?.addEventListener('click', handler);
}
async function renderTeacherTools() { if (!$('#dashboard-panel-overview') || $('#phase3-teacher-tools')) return; $('#dashboard-panel-overview .metric-grid').insertAdjacentHTML('afterend', '<article class="dashboard-card phase3-persistence-card" id="phase3-teacher-tools"><div class="targeting-heading"><span class="mini-label">TARGETED ACCESS CONTROL</span><h3>Give the right learner the right path.</h3><p>Choose a subject, grade, exact courses or modules, and a validity window.</p></div><div class="targeting-grid"><label class="phase3-field"><span>Target subject</span><select id="code-subject"><option value="spanish">🇪🇸 Spanish</option><option value="english">🇬🇧 English</option><option value="arabic">ع العربية</option></select></label><label class="phase3-field"><span>Grade level</span><select id="code-grade"><option>الصف الأول الثانوي</option><option>الصف الثاني الثانوي</option><option>الصف الثالث الثانوي</option></select></label><label class="phase3-field"><span>Unlock mode</span><select id="code-scope"><option value="specific">Specific courses / modules</option><option value="all">All content for this grade</option></select></label><label class="phase3-field"><span>Validity</span><select id="code-duration"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">Full academic year</option></select></label><div class="target-option-box" id="code-target-options"><span class="mini-label">SELECT UNITS</span><div id="code-course-options">Loading courses…</div></div><div class="phase3-code-actions"><button class="btn btn-primary" id="phase3-generate-code" type="button"><span>Generate targeted code</span><span>↗</span></button><strong id="phase3-generated-code"></strong><div id="phase3-code-message" class="phase3-message"></div></div></div><div class="code-history"><div class="dashboard-card-head"><div><span class="mini-label">CODE HISTORY</span><h3>Active invitations.</h3></div><span class="panel-note">EXPIRY AWARE <i></i></span></div><div class="code-history-wrap"><table class="code-history-table"><thead><tr><th>Code</th><th>Target</th><th>Validity</th><th>Status</th></tr></thead><tbody id="phase3-code-history"></tbody></table></div></div></article>');
  $('#dashboard-panel-overview').insertAdjacentHTML('beforeend', '<section class="teacher-library course-library" id="teacher-course-library-wrap"><div class="teacher-library-heading"><div><span class="mini-label">COURSE LIBRARY</span><h3>Manage your subject courses.</h3></div><span class="panel-note">OWNER CONTROL <i></i></span></div><div id="teacher-course-library"></div></section>');
  $('#dashboard-panel-lesson .lesson-form').insertAdjacentHTML('afterend', '<section class="teacher-library" id="teacher-lesson-library-wrap"><div class="teacher-library-heading"><div><span class="mini-label">LIVE CONTENT LIBRARY</span><h3>Edit or remove published lesson assets.</h3></div><span class="panel-note">DATABASE CRUD <i></i></span></div><div id="teacher-lesson-library"></div></section>'); $('#dashboard-panel-questions .question-bank-grid').insertAdjacentHTML('afterend', '<section class="teacher-library" id="teacher-question-library-wrap"><div class="teacher-library-heading"><div><span class="mini-label">QUESTION BANK RECORDS</span><h3>Every parsed bank stays editable.</h3></div></div><div id="teacher-question-library"></div></section>'); bindContentActions(); await refreshTeacherTools(); }
async function refreshTeacherTools() { const [{ courses }, me] = await Promise.all([api('/api/teacher/courses'), api('/api/me')]); teacherCourses = courses; renderContentLibraries(); const subject = $('#code-subject'); subject.innerHTML = `<option value="${escapeHtml(me.user?.subject || 'spanish')}">${escapeHtml(subjectLabel(me.user?.subject || 'spanish', document.documentElement.lang))}</option>`; subject.value = me.user?.subject || 'spanish'; subject.disabled = true; const grade = $('#code-grade'); const scope = $('#code-scope'); const renderOptions = () => { const matches = teacherCourses.filter((course) => course.subject === subject.value && course.grade === grade.value); $('#code-target-options').classList.toggle('is-all', scope.value === 'all'); $('#code-course-options').innerHTML = scope.value === 'all' ? '<p class="target-all-copy">All matching courses and modules will unlock.</p>' : matches.length ? matches.map((course) => `<label class="target-course-check"><input type="checkbox" value="${course.id}" data-target-course /><span><strong>${escapeHtml(course.title)}</strong><small>${course.lessonCount} lessons</small></span></label>${course.modules.map((module) => `<label class="target-module-check"><input type="checkbox" value="${module.id}" data-target-module /><span>Unit ${module.unitNumber} · ${escapeHtml(module.title)} <small>${module.lessonCount} lessons</small></span></label>`).join('')}`).join('') : '<p class="target-all-copy">No matching content yet. Create a lesson for this subject and grade first.</p>'; }; [subject, grade, scope].forEach((control) => control.onchange = renderOptions); renderOptions(); const { codes } = await api('/api/teacher/access-codes'); $('#phase3-code-history').innerHTML = codes.length ? codes.map((code) => `<tr><td><strong>${escapeHtml(code.code)}</strong></td><td>${escapeHtml(code.targetSubject)} · ${escapeHtml(code.targetGrade)}<small>${code.unlockScope === 'all' ? 'All grade content' : `${(code.targetCourseIds || []).length + (code.targetModuleIds || []).length} selected target(s)`}</small></td><td>${new Date(code.expiresAt).toLocaleDateString('en-GB')}</td><td><span class="code-status status-${code.status}">${code.status}</span></td></tr>`).join('') : '<tr><td colspan="4" class="table-empty">No codes generated yet.</td></tr>'; $('#phase3-generate-code').onclick = async () => { const message = $('#phase3-code-message'); const courseIds = $$('[data-target-course]:checked').map((input) => Number(input.value)); const moduleIds = $$('[data-target-module]:checked').map((input) => Number(input.value)); try { const result = await api('/api/teacher/access-codes', { method: 'POST', body: JSON.stringify({ targetSubject: subject.value, targetGrade: grade.value, unlockScope: scope.value, courseIds, moduleIds, duration: $('#code-duration').value }) }); $('#phase3-generated-code').textContent = result.code; formMessage(message, `Expires ${new Date(result.expiresAt).toLocaleDateString('en-GB')}.`, 'success'); await refreshTeacherTools(); } catch (error) { formMessage(message, error.message); } }; }
function renderEngagement(overview) { const bars = $('.chart-bars'); if (!bars) return; const values = overview.engagement || []; const max = Math.max(...values.map((item) => item.views), 1); bars.innerHTML = values.map((item) => `<span style="height:${Math.max(item.views ? (item.views / max) * 100 : 0, item.views ? 8 : 0)}%" title="${item.views} views"><b>${escapeHtml(item.label)}</b></span>`).join(''); const line = $('.chart-line'); if (line) line.innerHTML = ''; const total = values.reduce((sum, item) => sum + item.views, 0); const legend = $('.chart-legend strong'); if (legend) legend.innerHTML = `${total} <small>views in window</small>`; }
async function syncTeacherDashboard() { try { const [overview, directory, me, courseData] = await Promise.all([api('/api/teacher/overview'), api('/api/teacher/students'), api('/api/me'), api('/api/teacher/courses')]); teacherCourses = courseData.courses; if (me.user?.fullName && $('#teacher-display-name')) $('#teacher-display-name').textContent = me.user.fullName; const values = { students: overview.students, codes: overview.codes, views: overview.views, average: `${overview.average}%` }; Object.entries(values).forEach(([key, value]) => { const node = document.querySelector(`[data-metric="${key}"]`); if (node) node.textContent = value; }); const metricNotes = { students: `${overview.students} Students`, codes: `${overview.codes} Active Codes`, views: `${overview.views} Views`, average: `${overview.average}% Quiz Average` }; Object.entries(metricNotes).forEach(([key, value]) => { const note = document.querySelector(`[data-metric-note="${key}"]`); if (note) note.innerHTML = `<i class="trend-up">↗</i> ${value}`; }); renderEngagement(overview); $$('.graph-filter button').forEach((button) => { if (button.dataset.bound) return; button.dataset.bound = 'true'; button.addEventListener('click', async () => { $$('.graph-filter button').forEach((item) => item.classList.toggle('is-active', item === button)); const filtered = await api(`/api/teacher/overview?period=${button.textContent.replace('D', '')}`); renderEngagement(filtered); }); }); const today = overview.today || {}; const todayValues = { lessons: `${today.lessons} new lessons`, completed: `${today.completed} completions`, questions: `${today.questions} questions` }; Object.entries(todayValues).forEach(([key, value]) => { const node = $(`[data-today="${key}"]`); if (node) node.textContent = value; }); const dateNode = $('[data-today-date]'); if (dateNode) dateNode.textContent = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short' }).toUpperCase(); const body = $('#student-table-body'); if (body) { body.innerHTML = directory.students.map((student, index) => `<tr><td><span class="student-person"><i class="student-avatar avatar-${index % 4}">${escapeHtml(student.fullName.split(' ').map((part) => part[0]).join('').slice(0, 2))}</i><strong>${escapeHtml(student.fullName)}</strong></span></td><td>${escapeHtml(student.email || '')}</td><td>${escapeHtml(student.phone)}</td><td>${new Date(student.registrationDate).toLocaleDateString('en-GB')}</td><td><span class="course-count">${student.enrolledCourses} courses</span></td><td><span class="course-count">${student.activatedCodes} codes</span></td><td><span class="row-more">Live</span></td></tr>`).join('') || '<tr><td colspan="7" class="table-empty">No students yet.</td></tr>'; $('#student-count').textContent = directory.students.length; } const recent = $('#recent-lessons-content'); const lessons = courseData.courses.flatMap((course) => (course.lessons || []).map((lesson) => ({ ...lesson, subject: course.subject }))).slice(0, 5); if (recent) recent.innerHTML = lessons.length ? '<div class="recent-row recent-head"><span>LESSON</span><span>SUBJECT</span><span>MEDIA</span><span>STATUS</span></div>' + lessons.map((lesson) => `<div class="recent-row"><span><strong>${escapeHtml(lesson.title)}</strong><small>Unit ${String(lesson.unitNumber).padStart(2, '0')}</small></span><span class="subject-chip chip-${escapeHtml(lesson.subject)}">${escapeHtml(lesson.subject)}</span><span>${lesson.videoUrl ? 'Video' : 'Lesson'}${lesson.pdfUrl ? ' · PDF' : ''}</span><span class="status-live">Published</span></div>`).join('') : '<div class="recent-row"><span class="table-empty">No lessons published yet.</span></div>'; await renderTeacherTools(); await refreshTeacherTools(); } catch (error) { console.warn('Teacher dashboard sync:', error.message); } }
function bindHomeAuth() { const teacherForm = $('#teacher-form'); if (teacherForm) teacherForm.addEventListener('submit', (event) => { event.preventDefault(); event.stopImmediatePropagation(); window.location.href = '/teacher/login'; }, true); $$('.teacher-trigger').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); event.stopImmediatePropagation(); window.location.href = '/teacher/login'; }, true)); $$('#student-portal, #student-header-portal, #closing-cta').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); event.stopImmediatePropagation(); window.location.href = '/student/signup'; }, true)); $('#dashboard-logout')?.addEventListener('click', async (event) => { event.preventDefault(); event.stopImmediatePropagation(); await api('/api/auth/logout', { method: 'POST' }); window.location.href = '/'; }, true); const lessonForm = $('#lesson-form'); if (lessonForm) lessonForm.addEventListener('submit', async (event) => { event.preventDefault(); event.stopImmediatePropagation(); try { const result = await api('/api/teacher/lessons', { method: 'POST', body: JSON.stringify({ grade: $('#lesson-grade').value, unitNumber: Number($('#lesson-unit').value || 1), title: $('#lesson-title').value, videoUrl: $('#lesson-youtube').value || $('#lesson-video-file').files[0]?.name || '', pdfUrl: $('#lesson-pdf').files[0]?.name || '', coverUrl: $('#lesson-cover').files[0]?.name || '', rawQuestions: $('#question-source')?.value || '' }) }); formMessage($('#lesson-feedback'), `Saved “${result.lesson.title}” to the database. ${result.questionCount} questions attached.`, 'success'); await syncTeacherDashboard(); document.querySelector('[data-dashboard-tab="overview"]')?.click(); } catch (error) { formMessage($('#lesson-feedback'), error.message); } }, true); $('#question-source')?.addEventListener('input', (event) => { $('#question-char-count').textContent = `${event.target.value.length} characters`; }); const videoInput = $('#lesson-video-file'); const pdfInput = $('#lesson-pdf'); if (videoInput) videoInput.addEventListener('change', () => { const file = videoInput.files[0]; if (file) $('#video-file-name').textContent = file.name; }); if (pdfInput) pdfInput.addEventListener('change', () => { const file = pdfInput.files[0]; if (file) $('#pdf-file-name').textContent = file.name; }); }
function renderAdminPortal() {
  document.body.classList.add('phase3-route-mode');
  routeShell('<main class="admin-portal"><div class="admin-intro"><div class="phase3-kicker">LINGUAEDU / SUPER ADMIN <i></i></div><h1>Shape the<br /><em>teacher network.</em></h1><p class="phase3-auth-copy">Create subject-owned teacher workspaces and safely remove test data without touching the database directly.</p></div><section id="admin-content"><div class="phase3-auth-card compact"><form id="admin-login-form" class="phase3-form"><label class="phase3-field"><span>Admin username</span><input id="admin-login-username" required autocomplete="username" /></label><label class="phase3-field"><span>Admin password</span><input id="admin-login-password" type="password" required autocomplete="current-password" /></label><div id="admin-login-message" class="phase3-message"></div><button class="btn btn-primary phase3-submit" type="submit">Unlock admin portal ↗</button></form></div></section></main>');
  const content = $('#admin-content');
  const load = async () => {
    try { await api('/api/admin/me'); const data = await api('/api/admin/teachers'); render(data.teachers); }
    catch { const form = $('#admin-login-form'); form.onsubmit = async (event) => { event.preventDefault(); try { await api('/api/admin/login', { method: 'POST', body: JSON.stringify({ username: $('#admin-login-username').value, password: $('#admin-login-password').value }) }); await load(); } catch (error) { formMessage($('#admin-login-message'), error.message); } }; }
  };
  const cleanupConfirm = (title, detail, action, after) => {
    const overlay = document.createElement('div'); overlay.className = 'content-modal-backdrop'; overlay.innerHTML = '<div class="content-modal confirm-modal" role="dialog" aria-modal="true"><button class="content-modal-close" type="button">×</button><span class="mini-label">ADMIN DATA CLEANUP</span><h3>' + escapeHtml(title) + '</h3><p>' + escapeHtml(detail) + '</p><div class="content-modal-actions"><button class="btn btn-outline content-cancel" type="button">Cancel</button><button class="btn btn-danger content-confirm" type="button">Confirm delete</button></div></div>'; document.body.appendChild(overlay); const close = () => overlay.remove(); $$('.content-modal-close, .content-cancel', overlay).forEach((button) => button.addEventListener('click', close)); $('.content-confirm', overlay).onclick = async () => { $('.content-confirm', overlay).disabled = true; try { await action(); close(); await after?.(); } catch (error) { alert(error.message); $('.content-confirm', overlay).disabled = false; } };
  };
  const renderCleanup = (data) => {
    const cleanupResults = $('#admin-cleanup-results');
    const teacherRows = (data.teachers || []).map((teacher) => '<tr><td><strong>' + escapeHtml(teacher.fullName) + '</strong><small>' + escapeHtml(teacher.email || '') + '</small></td><td>' + escapeHtml(teacher.username || '') + '</td><td>' + escapeHtml(teacher.tenant?.name || 'Unassigned') + '</td><td><button class="asset-button asset-delete" data-cleanup-action="teacher" data-cleanup-id="' + teacher.id + '" data-cleanup-name="' + escapeHtml(teacher.fullName) + '">Delete teacher</button></td></tr>').join('');
    const studentRows = (data.students || []).map((student) => '<tr><td><strong>' + escapeHtml(student.fullName) + '</strong><small>' + escapeHtml(student.email || '') + '</small></td><td>' + escapeHtml(student.phone || '') + '</td><td><button class="asset-button asset-delete" data-cleanup-action="student" data-cleanup-id="' + student.id + '" data-cleanup-name="' + escapeHtml(student.fullName) + '">Delete student</button></td></tr>').join('');
    const codeRows = (data.accessCodes || []).map((code) => '<tr><td><strong>' + escapeHtml(code.code) + '</strong></td><td>' + escapeHtml(code.targetSubject || '') + ' · ' + escapeHtml(code.targetGrade || '') + '</td><td>' + escapeHtml(code.status || (code.redeemedBy ? 'redeemed' : 'active')) + '</td><td><button class="asset-button asset-delete" data-cleanup-action="code" data-cleanup-id="' + code.id + '" data-cleanup-name="' + escapeHtml(code.code) + '">Delete code</button></td></tr>').join('');
    cleanupResults.innerHTML = '<div class="cleanup-result-group"><span class="mini-label">TEACHERS (' + (data.teachers || []).length + ')</span><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Teacher</th><th>Username</th><th>Tenant</th><th></th></tr></thead><tbody>' + (teacherRows || '<tr><td colspan="4" class="table-empty">No teachers matched.</td></tr>') + '</tbody></table></div></div><div class="cleanup-result-group"><span class="mini-label">STUDENTS (' + (data.students || []).length + ')</span><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Student</th><th>Phone</th><th></th></tr></thead><tbody>' + (studentRows || '<tr><td colspan="3" class="table-empty">No students matched.</td></tr>') + '</tbody></table></div></div><div class="cleanup-result-group"><span class="mini-label">ACCESS CODES (' + (data.accessCodes || []).length + ')</span><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Code</th><th>Target</th><th>Status</th><th></th></tr></thead><tbody>' + (codeRows || '<tr><td colspan="4" class="table-empty">No access codes matched.</td></tr>') + '</tbody></table></div></div>';
  };
  const render = (teachers = []) => {
    const teacherRows = teachers.map((teacher) => `<tr><td><strong>${escapeHtml(teacher.fullName)}</strong><small>${escapeHtml(teacher.email || '')}</small></td><td>${escapeHtml(teacher.username || '')}</td><td><span class="subject-chip chip-${escapeHtml(teacher.tenant?.slug || 'spanish')}">${escapeHtml(teacher.tenant?.name || 'Unassigned')}</span></td><td>${formatDate(teacher.createdAt)}</td></tr>`).join('') || '<tr><td colspan="4" class="table-empty">No teachers created yet.</td></tr>';
    content.innerHTML = `<div class="admin-topline"><div><span class="mini-label">TEACHER DIRECTORY</span><h2>Assigned classrooms.</h2></div><button id="admin-logout" class="btn btn-outline" type="button">Log out ↗</button></div><div class="admin-grid"><form id="teacher-create-form" class="admin-card phase3-form"><span class="mini-label">ADD TEACHER</span><h3>New workspace</h3><label class="phase3-field"><span>Full name</span><input id="teacher-full-name" required /></label><div class="phase3-two-col"><label class="phase3-field"><span>Email</span><input id="teacher-email" type="email" required /></label><label class="phase3-field"><span>Phone</span><input id="teacher-phone" required /></label></div><div class="phase3-two-col"><label class="phase3-field"><span>Username</span><input id="teacher-username" required pattern="[a-zA-Z0-9._-]{3,80}" /></label><label class="phase3-field"><span>Subject / tenant</span><select id="teacher-subject"><option value="spanish">Spanish</option><option value="english">English</option><option value="arabic">Arabic</option></select></label></div><div class="phase3-two-col"><label class="phase3-field"><span>Password</span><input id="teacher-password" type="password" minlength="8" required /></label><label class="phase3-field"><span>Confirm password</span><input id="teacher-confirm-password" type="password" minlength="8" required /></label></div><div id="teacher-create-message" class="phase3-message"></div><button class="btn btn-primary phase3-submit" type="submit">Create teacher ↗</button></form><div class="admin-card"><span class="mini-label">ISOLATION MODEL</span><h3>One subject. One view.</h3><p class="admin-copy">Teacher accounts are assigned to a durable tenant. Courses, lessons, question banks, access codes, analytics, and redeemed students are filtered by teacher ownership before they reach the dashboard.</p><div class="admin-rule-list"><span><b>01</b> Subject tenant</span><span><b>02</b> Server-side ownership</span><span><b>03</b> Narrow student unlocks</span></div></div></div><section class="admin-card admin-cleanup-panel"><div class="admin-topline"><div><span class="mini-label">DATA CLEANUP</span><h3>Remove test records safely.</h3></div><span class="panel-note cleanup-warning">ADMIN ONLY</span></div><p class="admin-copy">Search by email, username, name, code, subject, or grade. Deleting a teacher also removes their courses and associated learning records. Deleting a student removes their learning records and releases redeemed codes.</p><form id="cleanup-search-form" class="cleanup-search-form"><input id="cleanup-search-input" class="text-input" minlength="2" placeholder="Search email, username, name, code, subject…" required /><button class="btn btn-outline" type="submit">Search records ↗</button></form><div id="cleanup-search-message" class="phase3-message" role="status"></div><div id="admin-cleanup-results" class="admin-cleanup-results"><div class="table-empty">Search for a record to begin.</div></div><div class="cleanup-danger-zone"><span class="mini-label">DANGER ZONE / TEST DATA ONLY</span><p>Deletes users whose records match known test markers such as <code>@linguora.test</code>, qa_, teacher, e2e, E2E, or QA. This does not delete production users unless they use these markers.</p><form id="cleanup-test-data-form" class="cleanup-search-form"><input id="cleanup-confirmation" class="text-input" placeholder="Type DELETE TEST DATA" autocomplete="off" required /><button class="btn btn-danger" type="submit">Delete all test data</button></form><div id="cleanup-test-data-message" class="phase3-message" role="status"></div></div></section><div class="admin-card admin-directory"><div class="admin-topline"><div><span class="mini-label">LIVE RECORDS</span><h3>Teachers in the system</h3></div><span class="panel-note">${teachers.length} RECORDS</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Teacher</th><th>Username</th><th>Subject tenant</th><th>Created</th></tr></thead><tbody>${teacherRows}</tbody></table></div></div>`;
    $('#admin-logout').onclick = async () => { await api('/api/admin/logout', { method: 'POST' }); window.location.reload(); };
    $('#teacher-create-form').onsubmit = async (event) => { event.preventDefault(); const message = $('#teacher-create-message'); const body = { fullName: $('#teacher-full-name').value, email: $('#teacher-email').value, phone: $('#teacher-phone').value, username: $('#teacher-username').value, password: $('#teacher-password').value, confirmPassword: $('#teacher-confirm-password').value, subject: $('#teacher-subject').value }; if (body.password !== body.confirmPassword) return formMessage(message, 'Passwords do not match.'); try { await api('/api/admin/teachers', { method: 'POST', body: JSON.stringify(body) }); formMessage(message, 'Teacher created and assigned to the selected subject.', 'success'); await load(); } catch (error) { formMessage(message, error.message); } };
    const searchForm = $('#cleanup-search-form');
    searchForm.onsubmit = async (event) => { event.preventDefault(); const message = $('#cleanup-search-message'); try { const result = await api('/api/admin/cleanup/search?q=' + encodeURIComponent($('#cleanup-search-input').value)); renderCleanup(result); formMessage(message, 'Search results updated.', 'success'); } catch (error) { formMessage(message, error.message); } };
    $('#admin-cleanup-results').onclick = (event) => { const button = event.target.closest('[data-cleanup-action]'); if (!button) return; const action = button.dataset.cleanupAction; const name = button.dataset.cleanupName; const path = action === 'teacher' ? '/api/admin/cleanup/teachers/' + button.dataset.cleanupId : action === 'student' ? '/api/admin/cleanup/students/' + button.dataset.cleanupId : '/api/admin/cleanup/access-codes/' + button.dataset.cleanupId; cleanupConfirm(action === 'code' ? 'Delete this access code?' : 'Delete ' + (action === 'teacher' ? 'this teacher and all owned data?' : 'this student and all learning data?'), action === 'teacher' ? 'This removes ' + name + ', their courses, lessons, question banks, access codes, analytics, and associated student unlock records.' : action === 'student' ? 'This removes ' + name + ', their profile, enrollments, progress, views, quiz attempts, and releases redeemed codes.' : 'This removes ' + name + ' and any entitlements created from it.', () => api(path, { method: 'DELETE' }), async () => searchForm.requestSubmit()); };
    $('#cleanup-test-data-form').onsubmit = (event) => { event.preventDefault(); const message = $('#cleanup-test-data-message'); const confirmation = $('#cleanup-confirmation').value.trim(); if (confirmation !== 'DELETE TEST DATA') return formMessage(message, 'Type DELETE TEST DATA exactly to continue.'); cleanupConfirm('Delete all marked test data?', 'This permanently removes matching QA/E2E test users and all of their associated records. This action cannot be undone.', async () => { await api('/api/admin/cleanup/test-data', { method: 'POST', body: JSON.stringify({ confirmation }) }); }, async () => { formMessage(message, 'Marked test data was deleted.', 'success'); $('#cleanup-confirmation').value = ''; await load(); }); };
  };
  load();
}
export function initPhase3() { const route = window.location.pathname.replace(/\/$/, '') || '/'; if (route === '/admin') return renderAdminPortal(); if (route === '/teacher/setup') return renderTeacherSetup(); if (route === '/teacher/login') return renderTeacherLogin(); if (route === '/student/signup') return renderStudentSignup(); if (route === '/student/login') return renderStudentLogin(); if (route === '/student') { renderStudentDashboard().catch((error) => routeShell(`<main class="phase3-auth-card compact"><h1>Sign in to<br /><em>your space.</em></h1><p>${escapeHtml(error.message)}</p><a class="btn btn-primary" href="/student/login">Student login ↗</a></main>`)); return; } bindHomeAuth(); api('/api/me').then(({ user }) => { if (user?.role === 'teacher' && window.openDashboard) { window.openDashboard(); syncTeacherDashboard(); } if (user?.role === 'student') window.location.href = '/student'; }).catch(() => {}); }
